class Solution {
public:
    vector<int> minEdgeReversals(int n, vector<vector<int>>& edges) {
        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], 0});
            adj[e[1]].push_back({e[0], 1});
        }
        vector<int> ans(n, 0);
        auto dfs1 = [&](auto& self, int u, int p) -> int {
            int cost = 0;
            for (auto& edge : adj[u]) {
                int v = edge.first, w = edge.second;
                if (v != p) cost += w + self(self, v, u);
            }
            return cost;
        };
        ans[0] = dfs1(dfs1, 0, -1);
        auto dfs2 = [&](auto& self, int u, int p) -> void {
            for (auto& edge : adj[u]) {
                int v = edge.first, w = edge.second;
                if (v != p) {
                    ans[v] = ans[u] + (w == 0 ? 1 : -1);
                    self(self, v, u);
                }
            }
        };
        dfs2(dfs2, 0, -1);
        return ans;
    }
};

class Solution {
    public int[] minEdgeReversals(int n, int[][] edges) {
        List<int[]>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(new int[]{e[1], 0});
            adj[e[1]].add(new int[]{e[0], 1});
        }
        int[] ans = new int[n];
        ans[0] = dfs1(0, -1, adj);
        dfs2(0, -1, adj, ans);
        return ans;
    }
    private int dfs1(int u, int p, List<int[]>[] adj) {
        int cost = 0;
        for (int[] edge : adj[u]) {
            int v = edge[0], w = edge[1];
            if (v != p) cost += w + dfs1(v, u, adj);
        }
        return cost;
    }
    private void dfs2(int u, int p, List<int[]>[] adj, int[] ans) {
        for (int[] edge : adj[u]) {
            int v = edge[0], w = edge[1];
            if (v != p) {
                ans[v] = ans[u] + (w == 0 ? 1 : -1);
                dfs2(v, u, adj, ans);
            }
        }
    }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number[]}
 */
var minEdgeReversals = function(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push([v, 0]);
        adj[v].push([u, 1]);
    }
    const ans = new Int32Array(n);
    function dfs1(u, p) {
        let cost = 0;
        for (const [v, w] of adj[u]) {
            if (v !== p) cost += w + dfs1(v, u);
        }
        return cost;
    }
    ans[0] = dfs1(0, -1);
    function dfs2(u, p) {
        for (const [v, w] of adj[u]) {
            if (v !== p) {
                ans[v] = ans[u] + (w === 0 ? 1 : -1);
                dfs2(v, u);
            }
        }
    }
    dfs2(0, -1);
    return Array.from(ans);
};
